package app.server.service;

import app.common.enums.AuctionStatus;
import app.common.enums.PacketType;
import app.common.models.Auction;
import app.common.models.PacketRes;
import app.common.dto.AuctionSummariesResponse;
import app.common.mapper.DtoMapper;
import app.server.handler.Server;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.time.LocalDateTime;
import java.time.temporal.ChronoUnit;
import java.util.List;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

public class AuctionScheduler {
    private static final Logger logger = LoggerFactory.getLogger(AuctionScheduler.class);
    private static AuctionScheduler instance;
    private final ScheduledExecutorService scheduler;
    private AuctionService auctionService;

    private AuctionScheduler() {
        this.scheduler = Executors.newScheduledThreadPool(10);
    }

    public static synchronized AuctionScheduler getInstance() {
        if (instance == null) {
            instance = new AuctionScheduler();
        }
        return instance;
    }

    public void init(AuctionService auctionService) {
        this.auctionService = auctionService;
        scheduleExistingOpenAuctions();
    }

    private void scheduleExistingOpenAuctions() {
        if (auctionService == null) return;
        List<AuctionSnapshot> snapshots = auctionService.getAuctions();
        for (AuctionSnapshot snapshot : snapshots) {
            Auction auction = snapshot.auction();
            if (auction.getStatus() == AuctionStatus.OPEN && auction.getStartTime() != null) {
                scheduleStart(auction.getId(), auction.getStartTime());
            }
            if (auction.getEndTime() != null
                && auction.getStatus() != AuctionStatus.FINISHED
                && auction.getStatus() != AuctionStatus.PAID
                && auction.getStatus() != AuctionStatus.CANCELED) {
                scheduleFinish(auction.getId(), auction.getEndTime());
            }
        }
    }

    public void scheduleStart(int auctionId, LocalDateTime startTime) {
        long delay = ChronoUnit.MILLIS.between(LocalDateTime.now(), startTime);
        if (delay < 0) delay = 0;

        scheduler.schedule(() -> {
            try {
                if (auctionService != null) {
                    boolean updated = auctionService.startOpenAuction(auctionId);
                    if (updated) {
                        logger.info("Auction {} started automatically.", auctionId);
                        broadcastAuctionList();
                    }
                }
            } catch (Exception e) {
                logger.error("Error starting auction {}", auctionId, e);
            }
        }, delay, TimeUnit.MILLISECONDS);
    }

    public void scheduleFinish(int auctionId, LocalDateTime endTime) {
        long delay = ChronoUnit.MILLIS.between(LocalDateTime.now(), endTime);
        if (delay < 0) delay = 0;

        scheduler.schedule(() -> {
            try {
                if (auctionService != null) {
                    boolean updated = auctionService.completeAuctionIfExpired(auctionId);
                    if (updated) {
                        logger.info("Auction {} finished automatically.", auctionId);
                        broadcastAuctionList();
                    }
                }
            } catch (Exception e) {
                logger.error("Error finishing auction {}", auctionId, e);
            }
        }, delay, TimeUnit.MILLISECONDS);
    }

    private void broadcastAuctionList() {
        try {
            AuctionSummariesResponse summariesResponse =
                new AuctionSummariesResponse(
                    auctionService.getAuctions().stream()
                        .map(snapshot -> DtoMapper.toAuctionSummary(snapshot.auction(), snapshot.item()))
                        .toList());
            Server.broadcast(
                PacketRes.of(true, PacketType.FETCH_AUCTION_SUMMARIES, summariesResponse), -1);
        } catch (Exception ex) {
            logger.error("Failed to broadcast updated auction list", ex);
        }
    }

    public void shutdown() {
        if (scheduler != null && !scheduler.isShutdown()) {
            scheduler.shutdownNow();
        }
    }
}

package app.server.service;

import app.common.enums.AuctionStatus;
import app.common.dto.AuctionPaidNoticeResponse;
import app.common.dto.AuctionSummariesResponse;
import app.common.dto.WalletUpdateResponse;
import app.common.enums.PacketType;
import app.common.models.Auction;
import app.common.models.BidTransaction;
import app.common.models.PacketRes;
import app.common.models.User;
import app.common.mapper.DtoMapper;
import app.server.handler.Server;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.math.BigDecimal;
import java.time.LocalDateTime;
import java.time.temporal.ChronoUnit;
import java.util.List;
import java.util.Optional;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

public class AuctionScheduler {
    private static final Logger logger = LoggerFactory.getLogger(AuctionScheduler.class);
    private static AuctionScheduler instance;
    private final ScheduledExecutorService scheduler;
    private AuctionService auctionService;
    private UserService userService;

    private AuctionScheduler() {
        this.scheduler = Executors.newScheduledThreadPool(10);
    }

    public static synchronized AuctionScheduler getInstance() {
        if (instance == null) {
            instance = new AuctionScheduler();
        }
        return instance;
    }

    public void init(AuctionService auctionService, UserService userService) {
        this.auctionService = auctionService;
        this.userService = userService;
        scheduleExistingOpenAuctions();
    }

    private void scheduleExistingOpenAuctions() {
        if (auctionService == null) return;
        List<AuctionSnapshot> snapshots = auctionService.getAuctions();
        for (AuctionSnapshot snapshot : snapshots) {
            Auction auction = snapshot.auction();
            if (auction.getStatus() == AuctionStatus.OPEN && auction.getStartTime() != null) {
                scheduleStart(auction.getId(), auction.getStartTime());
            }
            if (auction.getEndTime() != null
                && auction.getStatus() != AuctionStatus.FINISHED
                && auction.getStatus() != AuctionStatus.PAID
                && auction.getStatus() != AuctionStatus.CANCELED) {
                scheduleFinish(auction.getId(), auction.getEndTime());
            }
        }
    }

    public void scheduleStart(int auctionId, LocalDateTime startTime) {
        long delay = ChronoUnit.MILLIS.between(LocalDateTime.now(), startTime);
        if (delay < 0) delay = 0;

        scheduler.schedule(() -> {
            try {
                if (auctionService != null) {
                    boolean updated = auctionService.startOpenAuction(auctionId);
                    if (updated) {
                        logger.info("Auction {} started automatically.", auctionId);
                        broadcastAuctionList();
                    }
                }
            } catch (Exception e) {
                logger.error("Error starting auction {}", auctionId, e);
            }
        }, delay, TimeUnit.MILLISECONDS);
    }

    public void scheduleFinish(int auctionId, LocalDateTime endTime) {
        long delay = ChronoUnit.MILLIS.between(LocalDateTime.now(), endTime);
        if (delay < 0) delay = 0;

        scheduler.schedule(() -> {
            try {
                if (auctionService != null) {
                    boolean updated = auctionService.completeAuctionIfExpired(auctionId);
                    if (updated) {
                        logger.info("Auction {} finished automatically.", auctionId);
                        notifyPaymentIfNeeded(auctionId);
                        broadcastAuctionList();
                    }
                }
            } catch (Exception e) {
                logger.error("Error finishing auction {}", auctionId, e);
            }
        }, delay, TimeUnit.MILLISECONDS);
    }

    public void notifyPaymentIfNeeded(int auctionId) {
        if (auctionService == null) {
            return;
        }
        try {
            AuctionSnapshot snapshot = auctionService.getAuction(auctionId);
            if (snapshot.auction().getStatus() != AuctionStatus.PAID) {
                return;
            }
            Integer winnerId = snapshot.auction().getWinnerId();
            if (winnerId == null) {
                return;
            }
            Optional<BidTransaction> highestBid = auctionService.findHighestBid(auctionId);
            BigDecimal amount = highestBid.map(BidTransaction::getAmount).orElse(BigDecimal.ZERO);
            if (amount.signum() <= 0) {
                return;
            }
            String auctionName =
                snapshot.item() == null ? "Phiên #" + auctionId : snapshot.item().getName();
            AuctionPaidNoticeResponse sellerNotice =
                new AuctionPaidNoticeResponse(auctionId, auctionName, amount, "SELLER");
            AuctionPaidNoticeResponse winnerNotice =
                new AuctionPaidNoticeResponse(auctionId, auctionName, amount, "WINNER");
            Server.sendToUser(
                snapshot.auction().getSellerId(),
                PacketRes.of(true, PacketType.AUCTION_PAID_NOTICE, sellerNotice));
            Server.sendToUser(
                winnerId,
                PacketRes.of(true, PacketType.AUCTION_PAID_NOTICE, winnerNotice));
            sendWalletUpdate(snapshot.auction().getSellerId());
            sendWalletUpdate(winnerId);
        } catch (Exception ex) {
            logger.error("Failed to notify payment for auction {}", auctionId, ex);
        }
    }

    private void sendWalletUpdate(int userId) {
        if (userService == null) {
            return;
        }
        try {
            User user = userService.getById(userId);
            WalletUpdateResponse response = new WalletUpdateResponse(DtoMapper.toUserData(user));
            Server.sendToUser(userId, PacketRes.of(true, PacketType.WALLET_UPDATE, "OK", response));
        } catch (Exception ex) {
            logger.warn("Failed to send wallet update to user {}", userId, ex);
        }
    }

    private void broadcastAuctionList() {
        try {
            AuctionSummariesResponse summariesResponse =
                new AuctionSummariesResponse(
                    auctionService.getAuctions().stream()
                        .map(snapshot -> DtoMapper.toAuctionSummary(snapshot.auction(), snapshot.item()))
                        .toList());
            Server.broadcast(
                PacketRes.of(true, PacketType.FETCH_AUCTION_SUMMARIES, summariesResponse), -1);
        } catch (Exception ex) {
            logger.error("Failed to broadcast updated auction list", ex);
        }
    }

    public void shutdown() {
        if (scheduler != null && !scheduler.isShutdown()) {
            scheduler.shutdownNow();
        }
    }
}

package app.server.service;

import app.common.enums.AuctionStatus;
import app.common.enums.ItemType;
import app.common.enums.UserRole;
import app.common.exception.ServiceException;
import app.common.models.Auction;
import app.common.models.BidTransaction;
import app.common.models.Item;
import app.common.models.ItemFactory;
import app.common.models.User;
import app.server.dao.AuctionDAO;
import app.server.dao.BidDAO;
import app.server.dao.ItemDAO;
import app.server.dao.UserDAO;
import app.server.database.TransactionManager;
import java.time.Clock;
import java.time.LocalDateTime;
import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Optional;
import java.util.Set;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class AuctionService {
  private volatile List<AuctionSnapshot> snapshotCache;
  private final AuctionDAO auctionDAO;
  private final BidDAO bidDAO;
  private final ItemDAO itemDAO;
  private final UserDAO userDAO;
  private final TransactionManager transactionManager;
  private final Logger logger = LoggerFactory.getLogger(AuctionService.class);
  private final Clock clock;

  public AuctionService(
      AuctionDAO auctionDAO,
      BidDAO bidDAO,
      ItemDAO itemDAO,
      UserDAO userDAO,
      TransactionManager transactionManager) {
    this.auctionDAO = auctionDAO;
    this.bidDAO = bidDAO;
    this.itemDAO = itemDAO;
    this.userDAO = userDAO;
    this.transactionManager = transactionManager;
    this.clock = Clock.systemDefaultZone();
  }

  public Auction createAndStartAuctionWithItem(
      String name,
      String description,
      long startingPrice,
      long stepPrice,
      ItemType type,
      int durationMinutes,
      int requesterId,
      UserRole requesterRole,
      LocalDateTime startTime) {
    validateCreateAuctionRequest(
        name,
        description,
        startingPrice,
        stepPrice,
        type,
        durationMinutes,
        requesterId,
        requesterRole);
    Auction createdAuction =
        transactionManager.runInTransaction(
            conn -> {
              Item item =
                  ItemFactory.createItem(
                      name, requesterId, description, startingPrice, stepPrice, type);
              Item savedItem = itemDAO.save(conn, item);
              Auction auction =
                  new Auction(
                      savedItem.getId(),
                      requesterId,
                      startTime.plusMinutes(durationMinutes),
                      savedItem.getStartingPrice());
              auction.setStartTime(startTime);
              Auction created = auctionDAO.save(conn, auction);
              if (!startTime.isAfter(LocalDateTime.now(clock))) {
                created.start();
                auctionDAO.update(conn, created);
              }
              return created;
            });
    if (createdAuction.getStatus() == AuctionStatus.OPEN && createdAuction.getStartTime() != null) {
      AuctionScheduler.getInstance().scheduleStart(createdAuction.getId(), createdAuction.getStartTime());
    }
    if (createdAuction.getEndTime() != null
        && createdAuction.getStatus() != AuctionStatus.FINISHED
        && createdAuction.getStatus() != AuctionStatus.PAID
        && createdAuction.getStatus() != AuctionStatus.CANCELED) {
      AuctionScheduler.getInstance().scheduleFinish(createdAuction.getId(), createdAuction.getEndTime());
    }
    invalidateCache();
    return createdAuction;
  }

  public List<AuctionSnapshot> getAuctions() {
    List<AuctionSnapshot> cached = snapshotCache;
    if (cached != null) {
      return cached;
    }
    snapshotCache = auctionDAO.findAll().stream().map(this::toSnapshot).toList();
    return snapshotCache;
  }

  public List<AuctionSnapshot> getHistoryAuctions(int userId) {
    return getAuctions().stream()
        .filter(snapshot -> isSellerOrBidder(snapshot.auction(), userId))
        .toList();
  }

  public AuctionSnapshot getAuction(int auctionId) {
    List<AuctionSnapshot> cached = snapshotCache;
    if (cached != null) {
      for (AuctionSnapshot snapshot : cached) {
        if (snapshot.auctionId() == auctionId) {
          return snapshot;
        }
      }
    }
    Auction auction =
        auctionDAO
            .findById(auctionId)
            .orElseThrow(() -> new ServiceException("Không tìm thấy phiên ID: " + auctionId));
    return toSnapshot(auction);
  }

  public boolean isAuctionVersionCurrent(int auctionId, int knownVersion) {
    if (knownVersion < 0) {
      return false;
    }
    return getAuction(auctionId).version() == knownVersion;
  }

  public Optional<BidTransaction> completeAndGetHighestBid(int auctionId) {
    handleCompletion(auctionId);
    return bidDAO.findHighestBid(auctionId);
  }

  public boolean completeAuctionIfExpired(int auctionId) {
    return handleCompletion(auctionId);
  }

  public void cancelAuction(int auctionId, int requester, int expectedVersion) {
    transactionManager.runWithoutResult(
        conn -> {
          Auction auction = requireAuction(conn, auctionId);
          ensureCancelPermission(conn, auction, requester);
          AuctionStatus status = auction.getStatus();
          if (status == AuctionStatus.FINISHED || status == AuctionStatus.PAID) {
            throw new ServiceException("Không thể hủy phiên đã kết thúc hoặc đã thanh toán.");
          }
          auction.setStatus(AuctionStatus.CANCELED);
          releaseWallets(conn, auction);
          boolean ok = auctionDAO.updateIfVersionMatches(conn, auction, expectedVersion);
          if (!ok) {
            throw new ServiceException(
                "Dữ liệu phiên đã thay đổi, vui lòng tải lại trước khi duyệt.");
          }
        });
    invalidateCache();
  }

  public boolean startOpenAuction(int auctionId) {
    boolean[] updated = new boolean[] {false};
    transactionManager.runWithoutResult(
        conn -> {
          Auction auction = requireAuction(conn, auctionId);
          if (auction.getStatus() == AuctionStatus.OPEN) {
            auction.start();
            auctionDAO.update(conn, auction);
            updated[0] = true;
          }
        });
    if (updated[0]) {
      invalidateCache();
    }
    return updated[0];
  }

  public List<Integer> completeExpiredAuctions() {
    List<Integer> completedIds = new ArrayList<>();
    for (Auction auction : auctionDAO.findAll()) {
      if (!auction.isExpired()) {
        continue;
      }
      AuctionStatus status = auction.getStatus();
      if (status != AuctionStatus.OPEN && status != AuctionStatus.RUNNING) {
        continue;
      }
      if (handleCompletion(auction.getId())) {
        completedIds.add(auction.getId());
      }
    }
    return completedIds;
  }

  private boolean handleCompletion(int auctionId) {
    boolean completed =
        transactionManager.runInTransaction(
            conn -> {
              Auction auction = requireAuction(conn, auctionId);
              if (!auction.isExpired()) {
                return false;
              }
              AuctionStatus status = auction.getStatus();
              if (status != AuctionStatus.OPEN && status != AuctionStatus.RUNNING) {
                return false;
              }
              auction.setStatus(AuctionStatus.FINISHED);
              bidDAO
                  .findHighestBid(conn, auctionId)
                  .ifPresentOrElse(
                      bid -> {
                        auction.setWinnerId(bid.getBidderId());
                        logger.info(
                            "Phiên {} kết thúc. Winner: {}, Giá: {}",
                            auctionId,
                            bid.getBidderName(),
                            bid.getAmount());
                      },
                      () -> logger.info("Phiên {} kết thúc. Không có bid.", auctionId));
              BigDecimal winningAmount = settleWallets(conn, auction);
              if (auction.getWinnerId() != null && winningAmount.signum() > 0) {
                auction.setStatus(AuctionStatus.PAID);
              }
              auctionDAO.update(conn, auction);
              return true;
            });
    if (completed) {
      invalidateCache();
    }
    return completed;
  }

  public BigDecimal settleAuctionPayment(int auctionId) {
    BigDecimal[] amountRef = new BigDecimal[] {BigDecimal.ZERO};
    transactionManager.runWithoutResult(
        conn -> {
          Auction auction = requireAuction(conn, auctionId);
          if (auction.getStatus() == AuctionStatus.PAID) {
            return;
          }
          if (auction.getStatus() != AuctionStatus.FINISHED) {
            return;
          }
          BigDecimal winningAmount = settleWallets(conn, auction);
          if (auction.getWinnerId() != null && winningAmount.signum() > 0) {
            auction.setStatus(AuctionStatus.PAID);
            auctionDAO.update(conn, auction);
          }
          amountRef[0] = winningAmount;
        });
    if (amountRef[0].signum() > 0) {
      invalidateCache();
    }
    return amountRef[0];
  }

  private BigDecimal settleWallets(java.sql.Connection conn, Auction auction) {
    List<BidTransaction> bids = bidDAO.findByAuction(conn, auction.getId());
    Set<Integer> bidderIds = new LinkedHashSet<>();
    for (BidTransaction bid : bids) {
      bidderIds.add(bid.getBidderId());
    }
    BigDecimal winningAmount = BigDecimal.ZERO;
    Integer winnerId = auction.getWinnerId();
    for (Integer bidderId : bidderIds) {
      userDAO.lockRow(conn, bidderId);
      User user =
          userDAO
              .findById(conn, bidderId)
              .orElseThrow(() -> new ServiceException("Không tìm thấy user với id: " + bidderId));
      if (winnerId != null && winnerId.equals(bidderId)) {
        winningAmount = user.getWallet().commitFrozen(String.valueOf(auction.getId()));
      } else {
        user.getWallet().releaseFrozen(String.valueOf(auction.getId()));
      }
      userDAO.update(conn, user);
    }
    if (winnerId != null && winningAmount.signum() > 0) {
      userDAO.lockRow(conn, auction.getSellerId());
      User seller =
          userDAO
              .findById(conn, auction.getSellerId())
              .orElseThrow(
                  () -> new ServiceException("Không tìm thấy user với id: " + auction.getSellerId()));
      seller.getWallet().deposit(winningAmount);
      userDAO.update(conn, seller);
    }
    return winningAmount;
  }

  private void releaseWallets(java.sql.Connection conn, Auction auction) {
    List<BidTransaction> bids = bidDAO.findByAuction(conn, auction.getId());
    Set<Integer> bidderIds = new LinkedHashSet<>();
    for (BidTransaction bid : bids) {
      bidderIds.add(bid.getBidderId());
    }
    for (Integer bidderId : bidderIds) {
      userDAO.lockRow(conn, bidderId);
      User user =
          userDAO
              .findById(conn, bidderId)
              .orElseThrow(() -> new ServiceException("Không tìm thấy user với id: " + bidderId));
      user.getWallet().releaseFrozen(String.valueOf(auction.getId()));
      userDAO.update(conn, user);
    }
  }

  private void ensureCancelPermission(java.sql.Connection conn, Auction auction, int requesterId) {
    if (requesterId == auction.getSellerId()) {
      return;
    }
    User user =
        userDAO
            .findById(conn, requesterId)
            .orElseThrow(() -> new ServiceException("Không tìm thấy user với id: " + requesterId));
    if (user.getRole() != UserRole.ADMIN) {
      throw new ServiceException("Bạn không có quyền hủy phiên đấu giá này.");
    }
  }

  private void validateCreateAuctionRequest(
      String name,
      String description,
      long startingPrice,
      long stepPrice,
      ItemType type,
      int durationMinutes,
      int requesterId,
      UserRole requesterRole) {
    if (requesterId <= 0 || requesterRole == null) {
      throw new ServiceException("Dữ liệu người tạo phiên không hợp lệ.");
    }
    if (requesterRole != UserRole.SELLER && requesterRole != UserRole.ADMIN) {
      throw new ServiceException("Chỉ Seller/Admin được tạo phiên.");
    }
    if (name == null
        || name.isBlank()
        || description == null
        || description.isBlank()
        || startingPrice <= 0
        || stepPrice <= 0
        || durationMinutes <= 0
        || type == null) {
      throw new ServiceException("Dữ liệu phiên đấu giá không hợp lệ.");
    }
  }

  public void invalidateCache() {
    snapshotCache = null;
    logger.info("[CACHE] Auction cache invalidated");
  }

  private boolean isSellerOrBidder(Auction auction, int userId) {
    return auction.getSellerId() == userId
        || bidDAO.existsByAuctionAndUser(auction.getId(), userId);
  }

  private AuctionSnapshot toSnapshot(Auction auction) {
    Item item =
        itemDAO
            .findById(auction.getItemId())
            .orElseThrow(() -> new ServiceException("Không tìm thấy vật phẩm."));
    return new AuctionSnapshot(auction, item);
  }

  private Auction requireAuction(java.sql.Connection conn, int auctionId) {
    auctionDAO.lockRow(conn, auctionId);
    return auctionDAO
        .findById(conn, auctionId)
        .orElseThrow(() -> new ServiceException("Không tìm thấy phiên: " + auctionId));
  }
}

package app.server.service;

import app.common.enums.AuctionStatus;
import app.common.enums.ItemType;
import app.common.enums.UserRole;
import app.common.exception.ServiceException;
import app.common.models.Auction;
import app.common.models.BidTransaction;
import app.common.models.Item;
import app.common.models.ItemFactory;
import app.common.models.User;
import app.server.dao.AuctionDAO;
import app.server.dao.BidDAO;
import app.server.dao.ItemDAO;
import app.server.dao.UserDAO;
import app.server.database.TransactionManager;
import java.time.Clock;
import java.time.LocalDateTime;
import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Optional;
import java.util.Set;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class AuctionService {
  private volatile List<AuctionSnapshot> snapshotCache;
  private final AuctionDAO auctionDAO;
  private final BidDAO bidDAO;
  private final ItemDAO itemDAO;
  private final UserDAO userDAO;
  private final TransactionManager transactionManager;
  private final Logger logger = LoggerFactory.getLogger(AuctionService.class);
  private final Clock clock;

  public AuctionService(
      AuctionDAO auctionDAO,
      BidDAO bidDAO,
      ItemDAO itemDAO,
      UserDAO userDAO,
      TransactionManager transactionManager) {
    this.auctionDAO = auctionDAO;
    this.bidDAO = bidDAO;
    this.itemDAO = itemDAO;
    this.userDAO = userDAO;
    this.transactionManager = transactionManager;
    this.clock = Clock.systemDefaultZone();
  }

  public Auction createAndStartAuctionWithItem(
      String name,
      String description,
      long startingPrice,
      long stepPrice,
      ItemType type,
      int durationMinutes,
      int requesterId,
      UserRole requesterRole,
      LocalDateTime startTime) {
    validateCreateAuctionRequest(
        name,
        description,
        startingPrice,
        stepPrice,
        type,
        durationMinutes,
        requesterId,
        requesterRole);
    Auction createdAuction =
        transactionManager.runInTransaction(
            conn -> {
              Item item =
                  ItemFactory.createItem(
                      name, requesterId, description, startingPrice, stepPrice, type);
              Item savedItem = itemDAO.save(conn, item);
              Auction auction =
                  new Auction(
                      savedItem.getId(),
                      requesterId,
                      startTime.plusMinutes(durationMinutes),
                      savedItem.getStartingPrice());
              auction.setStartTime(startTime);
              Auction created = auctionDAO.save(conn, auction);
              if (!startTime.isAfter(LocalDateTime.now(clock))) {
                created.start();
                auctionDAO.update(conn, created);
              }
              return created;
            });
    if (createdAuction.getStatus() == AuctionStatus.OPEN && createdAuction.getStartTime() != null) {
      AuctionScheduler.getInstance().scheduleStart(createdAuction.getId(), createdAuction.getStartTime());
    }
    if (createdAuction.getEndTime() != null
        && createdAuction.getStatus() != AuctionStatus.FINISHED
        && createdAuction.getStatus() != AuctionStatus.PAID
        && createdAuction.getStatus() != AuctionStatus.CANCELED) {
      AuctionScheduler.getInstance().scheduleFinish(createdAuction.getId(), createdAuction.getEndTime());
    }
    invalidateCache();
    return createdAuction;
  }

  public List<AuctionSnapshot> getAuctions() {
    List<AuctionSnapshot> cached = snapshotCache;
    if (cached != null) {
      return cached;
    }
    snapshotCache = auctionDAO.findAll().stream().map(this::toSnapshot).toList();
    return snapshotCache;
  }

  public List<AuctionSnapshot> getHistoryAuctions(int userId) {
    return getAuctions().stream()
        .filter(snapshot -> isSellerOrBidder(snapshot.auction(), userId))
        .toList();
  }

  public AuctionSnapshot getAuction(int auctionId) {
    List<AuctionSnapshot> cached = snapshotCache;
    if (cached != null) {
      for (AuctionSnapshot snapshot : cached) {
        if (snapshot.auctionId() == auctionId) {
          return snapshot;
        }
      }
    }
    Auction auction =
        auctionDAO
            .findById(auctionId)
            .orElseThrow(() -> new ServiceException("Không tìm thấy phiên ID: " + auctionId));
    return toSnapshot(auction);
  }

  public boolean isAuctionVersionCurrent(int auctionId, int knownVersion) {
    if (knownVersion < 0) {
      return false;
    }
    return getAuction(auctionId).version() == knownVersion;
  }

  public Optional<BidTransaction> completeAndGetHighestBid(int auctionId) {
    handleCompletion(auctionId);
    return bidDAO.findHighestBid(auctionId);
  }

  public Optional<BidTransaction> findHighestBid(int auctionId) {
    return bidDAO.findHighestBid(auctionId);
  }

  public boolean completeAuctionIfExpired(int auctionId) {
    return handleCompletion(auctionId);
  }

  public void cancelAuction(int auctionId, int requester, int expectedVersion) {
    transactionManager.runWithoutResult(
        conn -> {
          Auction auction = requireAuction(conn, auctionId);
          ensureCancelPermission(conn, auction, requester);
          AuctionStatus status = auction.getStatus();
          if (status == AuctionStatus.FINISHED || status == AuctionStatus.PAID) {
            throw new ServiceException("Không thể hủy phiên đã kết thúc hoặc đã thanh toán.");
          }
          auction.setStatus(AuctionStatus.CANCELED);
          releaseWallets(conn, auction);
          boolean ok = auctionDAO.updateIfVersionMatches(conn, auction, expectedVersion);
          if (!ok) {
            throw new ServiceException(
                "Dữ liệu phiên đã thay đổi, vui lòng tải lại trước khi duyệt.");
          }
        });
    invalidateCache();
  }

  public boolean startOpenAuction(int auctionId) {
    boolean[] updated = new boolean[] {false};
    transactionManager.runWithoutResult(
        conn -> {
          Auction auction = requireAuction(conn, auctionId);
          if (auction.getStatus() == AuctionStatus.OPEN) {
            auction.start();
            auctionDAO.update(conn, auction);
            updated[0] = true;
          }
        });
    if (updated[0]) {
      invalidateCache();
    }
    return updated[0];
  }

  public List<Integer> completeExpiredAuctions() {
    List<Integer> completedIds = new ArrayList<>();
    for (Auction auction : auctionDAO.findAll()) {
      if (!auction.isExpired()) {
        continue;
      }
      AuctionStatus status = auction.getStatus();
      if (status != AuctionStatus.OPEN && status != AuctionStatus.RUNNING) {
        continue;
      }
      if (handleCompletion(auction.getId())) {
        completedIds.add(auction.getId());
      }
    }
    return completedIds;
  }

  private boolean handleCompletion(int auctionId) {
    boolean completed =
        transactionManager.runInTransaction(
            conn -> {
              Auction auction = requireAuction(conn, auctionId);
              if (!auction.isExpired()) {
                return false;
              }
              AuctionStatus status = auction.getStatus();
              if (status != AuctionStatus.OPEN && status != AuctionStatus.RUNNING) {
                return false;
              }
              auction.setStatus(AuctionStatus.FINISHED);
              bidDAO
                  .findHighestBid(conn, auctionId)
                  .ifPresentOrElse(
                      bid -> {
                        auction.setWinnerId(bid.getBidderId());
                        logger.info(
                            "Phiên {} kết thúc. Winner: {}, Giá: {}",
                            auctionId,
                            bid.getBidderName(),
                            bid.getAmount());
                      },
                      () -> logger.info("Phiên {} kết thúc. Không có bid.", auctionId));
              BigDecimal winningAmount = settleWallets(conn, auction);
              if (auction.getWinnerId() != null && winningAmount.signum() > 0) {
                auction.setStatus(AuctionStatus.PAID);
              }
              auctionDAO.update(conn, auction);
              return true;
            });
    if (completed) {
      invalidateCache();
    }
    return completed;
  }

  public BigDecimal settleAuctionPayment(int auctionId) {
    BigDecimal[] amountRef = new BigDecimal[] {BigDecimal.ZERO};
    transactionManager.runWithoutResult(
        conn -> {
          Auction auction = requireAuction(conn, auctionId);
          if (auction.getStatus() == AuctionStatus.PAID) {
            return;
          }
          if (auction.getStatus() != AuctionStatus.FINISHED) {
            return;
          }
          BigDecimal winningAmount = settleWallets(conn, auction);
          if (auction.getWinnerId() != null && winningAmount.signum() > 0) {
            auction.setStatus(AuctionStatus.PAID);
            auctionDAO.update(conn, auction);
          }
          amountRef[0] = winningAmount;
        });
    if (amountRef[0].signum() > 0) {
      invalidateCache();
    }
    return amountRef[0];
  }

  private BigDecimal settleWallets(java.sql.Connection conn, Auction auction) {
    List<BidTransaction> bids = bidDAO.findByAuction(conn, auction.getId());
    Set<Integer> bidderIds = new LinkedHashSet<>();
    for (BidTransaction bid : bids) {
      bidderIds.add(bid.getBidderId());
    }
    BigDecimal winningAmount = BigDecimal.ZERO;
    Integer winnerId = auction.getWinnerId();
    for (Integer bidderId : bidderIds) {
      userDAO.lockRow(conn, bidderId);
      User user =
          userDAO
              .findById(conn, bidderId)
              .orElseThrow(() -> new ServiceException("Không tìm thấy user với id: " + bidderId));
      if (winnerId != null && winnerId.equals(bidderId)) {
        winningAmount = user.getWallet().commitFrozen(String.valueOf(auction.getId()));
      } else {
        user.getWallet().releaseFrozen(String.valueOf(auction.getId()));
      }
      userDAO.update(conn, user);
    }
    if (winnerId != null && winningAmount.signum() > 0) {
      userDAO.lockRow(conn, auction.getSellerId());
      User seller =
          userDAO
              .findById(conn, auction.getSellerId())
              .orElseThrow(
                  () -> new ServiceException("Không tìm thấy user với id: " + auction.getSellerId()));
      seller.getWallet().deposit(winningAmount);
      userDAO.update(conn, seller);
    }
    return winningAmount;
  }

  private void releaseWallets(java.sql.Connection conn, Auction auction) {
    List<BidTransaction> bids = bidDAO.findByAuction(conn, auction.getId());
    Set<Integer> bidderIds = new LinkedHashSet<>();
    for (BidTransaction bid : bids) {
      bidderIds.add(bid.getBidderId());
    }
    for (Integer bidderId : bidderIds) {
      userDAO.lockRow(conn, bidderId);
      User user =
          userDAO
              .findById(conn, bidderId)
              .orElseThrow(() -> new ServiceException("Không tìm thấy user với id: " + bidderId));
      user.getWallet().releaseFrozen(String.valueOf(auction.getId()));
      userDAO.update(conn, user);
    }
  }

  private void ensureCancelPermission(java.sql.Connection conn, Auction auction, int requesterId) {
    if (requesterId == auction.getSellerId()) {
      return;
    }
    User user =
        userDAO
            .findById(conn, requesterId)
            .orElseThrow(() -> new ServiceException("Không tìm thấy user với id: " + requesterId));
    if (user.getRole() != UserRole.ADMIN) {
      throw new ServiceException("Bạn không có quyền hủy phiên đấu giá này.");
    }
  }

  private void validateCreateAuctionRequest(
      String name,
      String description,
      long startingPrice,
      long stepPrice,
      ItemType type,
      int durationMinutes,
      int requesterId,
      UserRole requesterRole) {
    if (requesterId <= 0 || requesterRole == null) {
      throw new ServiceException("Dữ liệu người tạo phiên không hợp lệ.");
    }
    if (requesterRole != UserRole.SELLER && requesterRole != UserRole.ADMIN) {
      throw new ServiceException("Chỉ Seller/Admin được tạo phiên.");
    }
    if (name == null
        || name.isBlank()
        || description == null
        || description.isBlank()
        || startingPrice <= 0
        || stepPrice <= 0
        || durationMinutes <= 0
        || type == null) {
      throw new ServiceException("Dữ liệu phiên đấu giá không hợp lệ.");
    }
  }

  public void invalidateCache() {
    snapshotCache = null;
    logger.info("[CACHE] Auction cache invalidated");
  }

  private boolean isSellerOrBidder(Auction auction, int userId) {
    return auction.getSellerId() == userId
        || bidDAO.existsByAuctionAndUser(auction.getId(), userId);
  }

  private AuctionSnapshot toSnapshot(Auction auction) {
    Item item =
        itemDAO
            .findById(auction.getItemId())
            .orElseThrow(() -> new ServiceException("Không tìm thấy vật phẩm."));
    return new AuctionSnapshot(auction, item);
  }

  private Auction requireAuction(java.sql.Connection conn, int auctionId) {
    auctionDAO.lockRow(conn, auctionId);
    return auctionDAO
        .findById(conn, auctionId)
        .orElseThrow(() -> new ServiceException("Không tìm thấy phiên: " + auctionId));
  }
}

package app.server.handler;

import app.common.dto.SettleWalletRequest;
import app.common.dto.WalletUpdateResponse;
import app.common.dto.AuctionSummariesResponse;
import app.common.enums.PacketType;
import app.common.exception.ServiceException;
import app.common.mapper.DtoMapper;
import app.common.models.PacketReq;
import app.common.models.PacketRes;
import app.common.models.User;
import app.server.service.AuctionService;
import app.server.service.UserService;
import app.server.service.AuctionSnapshot;
import java.util.List;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/** SettleWalletCommand. */
public class SettleWalletCommand implements Command {
  private static final Logger logger = LoggerFactory.getLogger(SettleWalletCommand.class);
  private final AuctionService auctionService;
  private final UserService userService;

  /** SettleWalletCommand. */
  public SettleWalletCommand(AuctionService auctionService, UserService userService) {
    this.auctionService = auctionService;
    this.userService = userService;
  }

  @Override
  public void execute(ClientHandler clientHandler, PacketReq packet) {
    try {
      if (!clientHandler.isAuthenticated()) {
        sendError(clientHandler, "Authentication required");
        return;
      }
      SettleWalletRequest request = packet.getData(SettleWalletRequest.class);
      if (request == null || request.auctionId() <= 0) {
        sendError(clientHandler, "Dữ liệu phiên đấu giá không hợp lệ.");
        return;
      }
      int auctionId = request.auctionId();
      int userId = clientHandler.getUser().getId();
      auctionService.completeAndGetHighestBid(auctionId);
      List<AuctionSnapshot> snapshots = auctionService.getAuctions();
      AuctionSummariesResponse summariesResponse =
          new AuctionSummariesResponse(
              snapshots.stream()
                  .map(snapshot -> DtoMapper.toAuctionSummary(snapshot.auction(), snapshot.item()))
                  .toList());
      Server.broadcast(PacketRes.of(true, PacketType.FETCH_AUCTION_SUMMARIES, summariesResponse), -1);
      User updated = userService.getById(userId);
      WalletUpdateResponse response = new WalletUpdateResponse(DtoMapper.toUserData(updated));
      clientHandler.sendPacket(
          PacketRes.of(true, PacketType.WALLET_UPDATE, "Cập nhật ví thành công.", response));
    } catch (ServiceException e) {
      logger.warn("Settle wallet failed: {}", e.getMessage());
      sendError(clientHandler, e.getMessage());
    } catch (Exception e) {
      logger.error("Unexpected settle wallet error", e);
      sendError(clientHandler, "Không thể cập nhật ví.");
    }
  }

  private void sendError(ClientHandler clientHandler, String message) {
    clientHandler.sendPacket(PacketRes.error(PacketType.WALLET_UPDATE, message));
  }
}

package app.server.handler;

import app.common.dto.AuctionPaidNoticeResponse;
import app.common.dto.AuctionSummariesResponse;
import app.common.dto.SettleWalletRequest;
import app.common.dto.WalletUpdateResponse;
import app.common.enums.PacketType;
import app.common.exception.ServiceException;
import app.common.mapper.DtoMapper;
import app.common.models.PacketReq;
import app.common.models.PacketRes;
import app.common.models.User;
import app.server.service.AuctionService;
import app.server.service.AuctionSnapshot;
import app.server.service.UserService;
import java.math.BigDecimal;
import java.util.List;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/** SettleWalletCommand. */
public class SettleWalletCommand implements Command {
  private static final Logger logger = LoggerFactory.getLogger(SettleWalletCommand.class);
  private final AuctionService auctionService;
  private final UserService userService;

  /** SettleWalletCommand. */
  public SettleWalletCommand(AuctionService auctionService, UserService userService) {
    this.auctionService = auctionService;
    this.userService = userService;
  }

  @Override
  public void execute(ClientHandler clientHandler, PacketReq packet) {
    try {
      if (!clientHandler.isAuthenticated()) {
        sendError(clientHandler, "Authentication required");
        return;
      }
      SettleWalletRequest request = packet.getData(SettleWalletRequest.class);
      if (request == null || request.auctionId() <= 0) {
        sendError(clientHandler, "Dữ liệu phiên đấu giá không hợp lệ.");
        return;
      }
      int auctionId = request.auctionId();
      int userId = clientHandler.getUser().getId();
      auctionService.completeAndGetHighestBid(auctionId);
      AuctionSnapshot snapshot = auctionService.getAuction(auctionId);
      BigDecimal paidAmount = auctionService.settleAuctionPayment(auctionId);
      if (paidAmount.signum() > 0 && snapshot.auction().getWinnerId() != null) {
        String auctionName = snapshot.item() == null ? "Phiên #" + auctionId : snapshot.item().getName();
        AuctionPaidNoticeResponse sellerNotice =
            new AuctionPaidNoticeResponse(auctionId, auctionName, paidAmount, "SELLER");
        AuctionPaidNoticeResponse winnerNotice =
            new AuctionPaidNoticeResponse(auctionId, auctionName, paidAmount, "WINNER");
        Server.sendToUser(
            snapshot.auction().getSellerId(),
            PacketRes.of(true, PacketType.AUCTION_PAID_NOTICE, sellerNotice));
        Server.sendToUser(
            snapshot.auction().getWinnerId(),
            PacketRes.of(true, PacketType.AUCTION_PAID_NOTICE, winnerNotice));
      }
      List<AuctionSnapshot> snapshots = auctionService.getAuctions();
      AuctionSummariesResponse summariesResponse =
          new AuctionSummariesResponse(
              snapshots.stream()
                  .map(snapshotItem -> DtoMapper.toAuctionSummary(snapshotItem.auction(), snapshotItem.item()))
                  .toList());
      Server.broadcast(
          PacketRes.of(true, PacketType.FETCH_AUCTION_SUMMARIES, summariesResponse), -1);
      User updated = userService.getById(userId);
      WalletUpdateResponse response = new WalletUpdateResponse(DtoMapper.toUserData(updated));
      clientHandler.sendPacket(
          PacketRes.of(true, PacketType.WALLET_UPDATE, "Cập nhật ví thành công.", response));
    } catch (ServiceException e) {
      logger.warn("Settle wallet failed: {}", e.getMessage());
      sendError(clientHandler, e.getMessage());
    } catch (Exception e) {
      logger.error("Unexpected settle wallet error", e);
      sendError(clientHandler, "Không thể cập nhật ví.");
    }
  }

  private void sendError(ClientHandler clientHandler, String message) {
    clientHandler.sendPacket(PacketRes.error(PacketType.WALLET_UPDATE, message));
  }
}

package app.server.service;

import app.common.enums.AuctionStatus;
import app.common.dto.AuctionPaidNoticeResponse;
import app.common.dto.AuctionSummariesResponse;
import app.common.dto.WalletUpdateResponse;
import app.common.enums.PacketType;
import app.common.models.Auction;
import app.common.models.BidTransaction;
import app.common.models.PacketRes;
import app.common.models.User;
import app.common.mapper.DtoMapper;
import app.server.handler.Server;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.math.BigDecimal;
import java.time.LocalDateTime;
import java.time.temporal.ChronoUnit;
import java.util.List;
import java.util.Optional;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

public class AuctionScheduler {
    private static final Logger logger = LoggerFactory.getLogger(AuctionScheduler.class);
    private static AuctionScheduler instance;
    private final ScheduledExecutorService scheduler;
    private AuctionService auctionService;
    private UserService userService;

    private AuctionScheduler() {
        this.scheduler = Executors.newScheduledThreadPool(10);
    }

    public static synchronized AuctionScheduler getInstance() {
        if (instance == null) {
            instance = new AuctionScheduler();
        }
        return instance;
    }

    public void init(AuctionService auctionService, UserService userService) {
        this.auctionService = auctionService;
        this.userService = userService;
        scheduleExistingOpenAuctions();
    }

    private void scheduleExistingOpenAuctions() {
        if (auctionService == null) return;
        List<AuctionSnapshot> snapshots = auctionService.getAuctions();
        for (AuctionSnapshot snapshot : snapshots) {
            Auction auction = snapshot.auction();
            if (auction.getStatus() == AuctionStatus.OPEN && auction.getStartTime() != null) {
                scheduleStart(auction.getId(), auction.getStartTime());
            }
            if (auction.getEndTime() != null
                && auction.getStatus() != AuctionStatus.FINISHED
                && auction.getStatus() != AuctionStatus.PAID
                && auction.getStatus() != AuctionStatus.CANCELED) {
                scheduleFinish(auction.getId(), auction.getEndTime());
            }
        }
    }

    public void scheduleStart(int auctionId, LocalDateTime startTime) {
        long delay = ChronoUnit.MILLIS.between(LocalDateTime.now(), startTime);
        if (delay < 0) delay = 0;

        scheduler.schedule(() -> {
            try {
                if (auctionService != null) {
                    boolean updated = auctionService.startOpenAuction(auctionId);
                    if (updated) {
                        logger.info("Auction {} started automatically.", auctionId);
                        broadcastAuctionList();
                    }
                }
            } catch (Exception e) {
                logger.error("Error starting auction {}", auctionId, e);
            }
        }, delay, TimeUnit.MILLISECONDS);
    }

    public void scheduleFinish(int auctionId, LocalDateTime endTime) {
        long delay = ChronoUnit.MILLIS.between(LocalDateTime.now(), endTime);
        if (delay < 0) delay = 0;

        scheduler.schedule(() -> {
            try {
                if (auctionService != null) {
                    boolean updated = auctionService.completeAuctionIfExpired(auctionId);
                    if (updated) {
                        logger.info("Auction {} finished automatically.", auctionId);
                        notifyPaymentIfNeeded(auctionId);
                        broadcastAuctionList();
                    }
                }
            } catch (Exception e) {
                logger.error("Error finishing auction {}", auctionId, e);
            }
        }, delay, TimeUnit.MILLISECONDS);
    }

    public void notifyPaymentIfNeeded(int auctionId) {
        if (auctionService == null) {
            return;
        }
        try {
            AuctionSnapshot snapshot = auctionService.getAuction(auctionId);
            if (snapshot.auction().getStatus() != AuctionStatus.PAID) {
                return;
            }
            Integer winnerId = snapshot.auction().getWinnerId();
            if (winnerId == null) {
                return;
            }
            Optional<BidTransaction> highestBid = auctionService.findHighestBid(auctionId);
            BigDecimal amount = highestBid.map(BidTransaction::getAmount).orElse(BigDecimal.ZERO);
            if (amount.signum() <= 0) {
                return;
            }
            String auctionName =
                snapshot.item() == null ? "Phiên #" + auctionId : snapshot.item().getName();
            AuctionPaidNoticeResponse sellerNotice =
                new AuctionPaidNoticeResponse(auctionId, auctionName, amount, "SELLER");
            AuctionPaidNoticeResponse winnerNotice =
                new AuctionPaidNoticeResponse(auctionId, auctionName, amount, "WINNER");
            Server.sendToUser(
                snapshot.auction().getSellerId(),
                PacketRes.of(true, PacketType.AUCTION_PAID_NOTICE, sellerNotice));
            Server.sendToUser(
                winnerId,
                PacketRes.of(true, PacketType.AUCTION_PAID_NOTICE, winnerNotice));
            sendWalletUpdate(snapshot.auction().getSellerId());
            sendWalletUpdate(winnerId);
        } catch (Exception ex) {
            logger.error("Failed to notify payment for auction {}", auctionId, ex);
        }
    }

    private void sendWalletUpdate(int userId) {
        if (userService == null) {
            return;
        }
        try {
            User user = userService.getById(userId);
            WalletUpdateResponse response = new WalletUpdateResponse(DtoMapper.toUserData(user));
            Server.sendToUser(userId, PacketRes.of(true, PacketType.WALLET_UPDATE, "OK", response));
        } catch (Exception ex) {
            logger.warn("Failed to send wallet update to user {}", userId, ex);
        }
    }

    private void broadcastAuctionList() {
        try {
            AuctionSummariesResponse summariesResponse =
                new AuctionSummariesResponse(
                    auctionService.getAuctions().stream()
                        .map(snapshot -> DtoMapper.toAuctionSummary(snapshot.auction(), snapshot.item()))
                        .toList());
            Server.broadcast(
                PacketRes.of(true, PacketType.FETCH_AUCTION_SUMMARIES, summariesResponse), -1);
        } catch (Exception ex) {
            logger.error("Failed to broadcast updated auction list", ex);
        }
    }

    public void shutdown() {
        if (scheduler != null && !scheduler.isShutdown()) {
            scheduler.shutdownNow();
        }
    }
}

package app.server.service;

import app.common.enums.AuctionStatus;
import app.common.dto.AuctionPaidNoticeResponse;
import app.common.dto.AuctionSummariesResponse;
import app.common.dto.WalletUpdateResponse;
import app.common.enums.PacketType;
import app.common.models.Auction;
import app.common.models.BidTransaction;
import app.common.models.PacketRes;
import app.common.models.User;
import app.common.mapper.DtoMapper;
import app.server.handler.Server;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.math.BigDecimal;
import java.time.LocalDateTime;
import java.time.temporal.ChronoUnit;
import java.util.List;
import java.util.Optional;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

public class AuctionScheduler {
    private static final Logger logger = LoggerFactory.getLogger(AuctionScheduler.class);
    private static AuctionScheduler instance;
    private final ScheduledExecutorService scheduler;
    private AuctionService auctionService;
    private UserService userService;

    private AuctionScheduler() {
        this.scheduler = Executors.newScheduledThreadPool(10);
    }

    public static synchronized AuctionScheduler getInstance() {
        if (instance == null) {
            instance = new AuctionScheduler();
        }
        return instance;
    }

    public void init(AuctionService auctionService, UserService userService) {
        this.auctionService = auctionService;
        this.userService = userService;
        scheduleExistingOpenAuctions();
    }

    private void scheduleExistingOpenAuctions() {
        if (auctionService == null) return;
        List<AuctionSnapshot> snapshots = auctionService.getAuctions();
        for (AuctionSnapshot snapshot : snapshots) {
            Auction auction = snapshot.auction();
            if (auction.getStatus() == AuctionStatus.OPEN && auction.getStartTime() != null) {
                scheduleStart(auction.getId(), auction.getStartTime());
            }
            if (auction.getEndTime() != null
                && auction.getStatus() != AuctionStatus.FINISHED
                && auction.getStatus() != AuctionStatus.PAID
                && auction.getStatus() != AuctionStatus.CANCELED) {
                scheduleFinish(auction.getId(), auction.getEndTime());
            }
        }
    }

    public void scheduleStart(int auctionId, LocalDateTime startTime) {
        long delay = ChronoUnit.MILLIS.between(LocalDateTime.now(), startTime);
        if (delay < 0) delay = 0;

        scheduler.schedule(() -> {
            try {
                if (auctionService != null) {
                    boolean updated = auctionService.startOpenAuction(auctionId);
                    if (updated) {
                        logger.info("Auction {} started automatically.", auctionId);
                        broadcastAuctionList();
                    }
                }
            } catch (Exception e) {
                logger.error("Error starting auction {}", auctionId, e);
            }
        }, delay, TimeUnit.MILLISECONDS);
    }

    public void scheduleFinish(int auctionId, LocalDateTime endTime) {
        long delay = ChronoUnit.MILLIS.between(LocalDateTime.now(), endTime);
        if (delay < 0) delay = 0;

        scheduler.schedule(() -> {
            try {
                if (auctionService != null) {
                    boolean updated = auctionService.completeAuctionIfExpired(auctionId);
                    if (updated) {
                        logger.info("Auction {} finished automatically.", auctionId);
                        notifyPaymentIfNeeded(auctionId);
                        broadcastAuctionList();
                    }
                }
            } catch (Exception e) {
                logger.error("Error finishing auction {}", auctionId, e);
            }
        }, delay, TimeUnit.MILLISECONDS);
    }

    public void notifyPaymentIfNeeded(int auctionId) {
        if (auctionService == null) {
            return;
        }
        try {
            AuctionSnapshot snapshot = auctionService.getAuction(auctionId);
            if (snapshot.auction().getStatus() != AuctionStatus.PAID) {
                return;
            }
            Integer winnerId = snapshot.auction().getWinnerId();
            if (winnerId == null) {
                return;
            }
            Optional<BidTransaction> highestBid = auctionService.findHighestBid(auctionId);
            BigDecimal amount = highestBid
                .map(bid -> BigDecimal.valueOf(bid.getAmount()))
                .orElse(BigDecimal.ZERO);
            if (amount.signum() <= 0) {
                return;
            }
            String auctionName =
                snapshot.item() == null ? "Phiên #" + auctionId : snapshot.item().getName();
            AuctionPaidNoticeResponse sellerNotice =
                new AuctionPaidNoticeResponse(auctionId, auctionName, amount, "SELLER");
            AuctionPaidNoticeResponse winnerNotice =
                new AuctionPaidNoticeResponse(auctionId, auctionName, amount, "WINNER");
            Server.sendToUser(
                snapshot.auction().getSellerId(),
                PacketRes.of(true, PacketType.AUCTION_PAID_NOTICE, sellerNotice));
            Server.sendToUser(
                winnerId,
                PacketRes.of(true, PacketType.AUCTION_PAID_NOTICE, winnerNotice));
            sendWalletUpdate(snapshot.auction().getSellerId());
            sendWalletUpdate(winnerId);
        } catch (Exception ex) {
            logger.error("Failed to notify payment for auction {}", auctionId, ex);
        }
    }

    private void sendWalletUpdate(int userId) {
        if (userService == null) {
            return;
        }
        try {
            User user = userService.getById(userId);
            WalletUpdateResponse response = new WalletUpdateResponse(DtoMapper.toUserData(user));
            Server.sendToUser(userId, PacketRes.of(true, PacketType.WALLET_UPDATE, "OK", response));
        } catch (Exception ex) {
            logger.warn("Failed to send wallet update to user {}", userId, ex);
        }
    }

    private void broadcastAuctionList() {
        try {
            AuctionSummariesResponse summariesResponse =
                new AuctionSummariesResponse(
                    auctionService.getAuctions().stream()
                        .map(snapshot -> DtoMapper.toAuctionSummary(snapshot.auction(), snapshot.item()))
                        .toList());
            Server.broadcast(
                PacketRes.of(true, PacketType.FETCH_AUCTION_SUMMARIES, summariesResponse), -1);
        } catch (Exception ex) {
            logger.error("Failed to broadcast updated auction list", ex);
        }
    }

    public void shutdown() {
        if (scheduler != null && !scheduler.isShutdown()) {
            scheduler.shutdownNow();
        }
    }
}
